fn encode_shift(s: Vec<char>) -> Vec<char> {
    s.into_iter()
        .map(|c| {
            // Calculate the new character by shifting 5 positions forward
            let shifted = ((c as u8 - b'a' + 5) % 26 + b'a') as char;
            shifted
        })
        .collect()
}

fn main() {
    // Example usage
    let input = vec!['a', 'b', 'c', 'z'];
    let encoded = encode_shift(input);
    println!("{:?}", encoded); // Output: ['f', 'g', 'h', 'e']
}